from collections import Counter, deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result

def _shape(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return frozenset((r - minr, c - minc) for r, c in cells)

def _corner_frame(cells):
    minr = min(r for r, c in cells); maxr = max(r for r, c in cells)
    minc = min(c for r, c in cells); maxc = max(c for r, c in cells)
    # A frame is an exact L: two complete adjacent bounding-box edges.
    for horizontal in (minr, maxr):
        for vertical in (minc, maxc):
            expected = ({(horizontal, c) for c in range(minc, maxc + 1)} |
                        {(r, vertical) for r in range(minr, maxr + 1)})
            if cells == expected:
                return minr, maxr, minc, maxc
    return None

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    comps = _components(grid)

    frames = []
    for color, cells in comps:
        if color == background:
            continue
        box = _corner_frame(cells)
        if box is not None:
            frames.append((len(cells), color, cells, box))
    if not frames:
        return out
    _, marker_color, marker_cells, (r0, r1, c0, c1) = max(frames)

    # The small object inside the L's bounding box is the shape exemplar.
    exemplars = []
    for color, cells in comps:
        if color == marker_color or color == background:
            continue
        if all(r0 <= r <= r1 and c0 <= c <= c1 for r, c in cells):
            exemplars.append((color, cells))
    if not exemplars:
        return out
    # The exemplar is the largest enclosed non-background object.
    _, exemplar = max(exemplars, key=lambda item: len(item[1]))
    target_shape = _shape(exemplar)

    for color, cells in comps:
        if cells == exemplar:
            continue
        if any(r0 <= r <= r1 and c0 <= c <= c1 for r, c in cells):
            continue
        if _shape(cells) == target_shape:
            for r, c in cells:
                out[r][c] = marker_color
    return out

